from solution import Entry, Report, solve

assert solve([]) == Report(0, 0, 0), 'fixture 0'
assert solve([Entry(3, 2, 1)]) == Report(1, 0, 3), 'fixture 1'
assert solve([Entry(4, 2, 4), Entry(4, 2, (-2))]) == Report(1, 1, 12), 'fixture 2'
assert solve([Entry(0, 1, 8), Entry(0, 0, 6), Entry(3, 1, 3)]) == Report(2, 1, 22), 'fixture 3'
assert solve([Entry(2, 2, 7), Entry(1, 3, (-1)), Entry(1, 3, 3), Entry(0, 2, 9)]) == Report(3, 1, 44), 'fixture 4'
assert solve([Entry(1, 3, (-2)), Entry(1, 2, (-1)), Entry(3, 1, (-1)), Entry(4, 3, 9), Entry(4, 2, 5)]) == Report(3, 2, 26), 'fixture 5'
assert solve([Entry(0, 3, 7), Entry(4, 1, 6), Entry(0, 1, 2), Entry(0, 3, 0), Entry(0, 0, 9), Entry(3, 3, 8)]) == Report(3, 3, 72), 'fixture 6'
assert solve([Entry(3, 0, 6), Entry(3, 1, 3), Entry(0, 0, 2), Entry(1, 3, 0), Entry(0, 3, (-1)), Entry(2, 1, 4), Entry(0, 3, 7)]) == Report(4, 3, 16), 'fixture 7'
assert solve([Entry(2, 3, 0), Entry(0, 2, 1), Entry(2, 1, 7), Entry(2, 1, 4), Entry(2, 1, 2), Entry(2, 2, 5), Entry(1, 0, 3), Entry(0, 3, (-2))]) == Report(3, 5, 6), 'fixture 8'
assert solve([Entry(3, 2, 1), Entry(0, 0, 5), Entry(0, 0, 0), Entry(4, 0, (-1)), Entry(1, 2, 4), Entry(4, 2, 9), Entry(0, 2, 2), Entry(4, 2, 3), Entry(1, 1, (-1))]) == Report(4, 5, 19), 'fixture 9'
assert solve([Entry(2, 1, 3), Entry(4, 2, 6), Entry(3, 3, (-2)), Entry(1, 3, 5), Entry(1, 0, 2), Entry(0, 3, 1), Entry(1, 1, 7), Entry(4, 1, 1), Entry(3, 1, 0), Entry(1, 3, 5)]) == Report(5, 5, 40), 'fixture 10'
assert solve([Entry(2, 2, 2), Entry(2, 1, 1), Entry(4, 0, 3), Entry(1, 1, 2), Entry(1, 1, 7), Entry(0, 1, (-1)), Entry(3, 3, (-2)), Entry(3, 3, 0), Entry(4, 0, 5), Entry(0, 3, 4), Entry(2, 0, 0)]) == Report(5, 6, 3), 'fixture 11'
assert solve([Entry(3, 0, 4), Entry(3, 1, 3), Entry(0, 1, 5), Entry(3, 2, (-2)), Entry(3, 1, 1), Entry(2, 2, 6), Entry(3, 0, 2), Entry(2, 1, (-2)), Entry(0, 3, 4), Entry(2, 2, 8), Entry(3, 0, 6), Entry(0, 0, 3)]) == Report(3, 9, 32), 'fixture 12'
assert solve([Entry(3, 0, 1)]) == Report(1, 0, 1), 'fixture 13'
assert solve([Entry(3, 2, 2), Entry(0, 1, 7)]) == Report(2, 0, 20), 'fixture 14'
assert solve([Entry(4, 0, 1), Entry(4, 1, 1), Entry(1, 2, (-2))]) == Report(2, 1, (-5)), 'fixture 15'
assert solve([Entry(4, 1, 5), Entry(4, 0, 6), Entry(1, 0, 8), Entry(0, 0, 5)]) == Report(3, 1, 23), 'fixture 16'
assert solve([Entry(2, 0, 0), Entry(1, 0, 3), Entry(1, 1, (-1)), Entry(2, 1, 0), Entry(1, 2, 2)]) == Report(2, 3, 3), 'fixture 17'
assert solve([Entry(4, 3, (-2)), Entry(1, 3, 6), Entry(3, 0, 2), Entry(4, 1, (-2)), Entry(4, 3, (-2)), Entry(3, 0, 0)]) == Report(3, 3, 18), 'fixture 18'
assert solve([Entry(1, 0, 5), Entry(3, 2, (-1)), Entry(3, 3, 5), Entry(0, 3, (-2)), Entry(4, 1, (-1)), Entry(1, 0, 3), Entry(2, 3, (-1))]) == Report(5, 2, (-12)), 'fixture 19'
assert solve([Entry(2, 3, (-1)), Entry(2, 0, (-1)), Entry(2, 2, 5), Entry(1, 3, 3), Entry(4, 2, 6), Entry(3, 0, 1), Entry(3, 0, 1), Entry(3, 0, 9)]) == Report(4, 4, 27), 'fixture 20'
assert solve([Entry(0, 0, 0), Entry(0, 1, 99), Entry(1, 0, (-1))]) == Report(2, 1, (-1)), 'fixture 21'
assert solve([Entry(1, 0, 5), Entry(2, 1, (-2)), Entry(1, 9, 9), Entry(3, 0, 1)]) == Report(3, 1, 2), 'fixture 22'
